// Ilustraciones de los platos terminados (recortadas de las imágenes de referencia de Sing, fondo transparente).
// Originales en assets/platos/ (el nombre del archivo es el id del plato). dishIcon() (js/dish-icons.js) las usa;
// si un plato no tiene imagen, usa su dibujo. Algunas son de platos para niveles futuros.
const DISH_IMAGES = {
  aeropuerto: 'data:image/webp;base64,',
  aji: 'data:image/webp;base64,',
  causa: 'data:image/webp;base64,',
  cebiche_pota: 'data:image/webp;base64,',
  chaufa: 'data:image/webp;base64,',
  chicha: 'data:image/webp;base64,',
  chijaukay: 'data:image/webp;base64,',
  huancaina: 'data:image/webp;base64,',
  lomo_saltado: 'data:image/webp;base64,',
  papa_rellena: 'data:image/webp;base64,',
  pollo_aji: 'data:image/webp;base64,',
  sopa_wantan: 'data:image/webp;base64,',
  tallarin_saltado: 'data:image/webp;base64,',
  tipakay: 'data:image/webp;base64,',
};
// el cebiche sin ají usa la misma ilustración
DISH_IMAGES.cebiche_sin = DISH_IMAGES.cebiche_pota;
const DISH_IMG = {};
const DISH_READY = Promise.all(Object.entries(DISH_IMAGES).map(([k, src]) => new Promise(res => { const im = new Image(); im.onload = () => { DISH_IMG[k] = im; res(); }; im.onerror = res; im.src = src; })));
